/// Returns the unique implicit system for a generated ValueSet, if exactly one is known.
/// Falls back from versioned canonical URLs to the base canonical URL.
pub fn implicit_system(valueset_url: &str) -> Option<&'static str> {
    if let Some(system) = implicit_system_exact(valueset_url) {
        return Some(system);
    }
    if let Some((base, _version)) = valueset_url.split_once('|') {
        return implicit_system_exact(base);
    }
    None
}

